{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C18"],
      "claim": "Grazoprevir, the closest analogue sharing the same P1 cyclopropyl acylsulfonamide, P2 bicyclic proline, P3 tert-leucine and macrocyclic carbamate scaffold, has an absolute oral bioavailability of 27% in humans, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Additional grazoprevir studies report bioavailability of 24–40% after multiple 200 mg doses in healthy subjects, reinforcing the high-F direction for this close structural analogue.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "A single-dose 25 mg grazoprevir study reported bioavailability of 10–17%, below the 20% threshold, indicating dose/formulation dependence and providing some contradictory evidence.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C29"],
      "claim": "Danoprevir, a macrocyclic HCV protease inhibitor with an isoindoline carbamate, has an absolute oral bioavailability of only 1.15% due to presystemic clearance; this is structurally relevant but less transferable than grazoprevir.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C08"],
      "claim": "SCH 900518, another macrocyclic HCV protease inhibitor with a cyclopropyl acylsulfonamide, showed a mean absolute bioavailability of 40.8% in humans, supporting that this class can achieve F ≥ 20%.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a macrocyclic HCV-protease-inhibitor-like acylsulfonamide most similar to grazoprevir, whose absolute oral bioavailability is approximately 27% (range 20–40%) in humans. Although a low-dose grazoprevir record and the low-F analogue danoprevir argue for caution, the higher transferability and consistent high-F measurements from the closest analogue support F ≥ 20%.",
  "evidence_gaps": [
    "No direct experimental bioavailability measurement for the query molecule.",
    "Grazoprevir bioavailability varies with dose and formulation, making the exact threshold prediction uncertain.",
    "Danoprevir's very low F demonstrates that minor structural changes in this class can cause high presystemic clearance, but the query's closer similarity to grazoprevir reduces this concern.",
    "No data on whether the isoindoline/gem-dimethyl modification alters intestinal efflux or hepatic first-pass metabolism relative to grazoprevir."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

